def UDPMessaging(udp_ip, udp_port):
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
        sock.bind((udp_ip, udp_port))
        while True:
            data, addr = sock.recvfrom(512)
            transaction_id, questions_count, _ = parseUDPpacket(data)
            if questions_count > 0:
                nameToResolve = data[12:data.find(b'\x00', 12)].decode()
                ip = resolveName(nameToResolve)
                if ip:
                    response = struct.pack('>H', transaction_id[0]) + b'\x81\x80' + struct.pack('>H', questions_count) + struct.pack('>H', 1) + struct.pack('>H', 0) + struct.pack('>H', 0) + data[12:] + struct.pack('>H', len(ip) + 2) + b'\x00\x01' + b'\x00\x01' + b'\x00\x00\x00\x3C' + b'\x00\x04' + socket.inet_aton(ip)
                    sendResponse(addr[0], response)

