from lxml import etree
from io import StringIO
from django.http import HttpResponse
from django.views.decorators.http import require_GET

@require_GET
def xpath_query(request):
    xpath_value = request.GET.get('xpath', None)
    xml_value = request.GET.get('xml', None)

    if xpath_value is None or xml_value is None:
        return HttpResponse(status=400)

    try:
        xml_parser = etree.XMLParser(recover=False)
        xml_doc = etree.parse(StringIO(xml_value), xml_parser)
        result = xml_doc.xpath(f"/tag[@id='{xpath_value}']")
        return HttpResponse(etree.tostring(result, pretty_print=True), content_type="application/xml")
    except (etree.XMLSyntaxError, ValueError):
        return HttpResponse(status=400)

